"""Freeze manually read expression/term/restriction spans before candidate creation."""
from datetime import datetime, timezone
import time
from scripts import prospectus_standalone_sections as prior
from legalmath.prospectus.successor.contracts import digest

ROOT, AUTH = prior.ROOT, prior.AUTH
PREP = AUTH / 'reviews/unquoted-definitions-349'
PLAN = 'docs/plans/prospectus-unquoted-definitions-2026-10-19.md'
# These excerpts are read from the selected source, not generated by the parser.
ROWS = [
    ('U01-registers', 'PARENTHETICAL_EXPLICATION',
     'Die Register der ICSDs (unter denen die Register zu\nverstehen sind, die jeder ICSD für seine Kunden über den Betrag ihres Anteils an den\nSchuldverschreibungen führt)',
     'Register', 'der ICSDs',
     'die jeder ICSD für seine Kunden über den Betrag ihres Anteils an den\nSchuldverschreibungen führt'),
    ('U02-capital', 'REFERENCE_EXPANSION',
     'Bezugnahmen in diesen\nAnleihebedingungen auf Kapital der Schuldverschreibungen schließen, soweit\nanwendbar, die folgenden Beträge ein: den Rückzahlungsbetrag der\nSchuldverschreibungen;\nden\nvorzeitigen\nRückzahlungsbetrag\nder\nSchuldverschreibungen;  den Wahl-Rückzahlungsbetrag (Call)\nder Schuldverschreibungen;   sowie jeden\nAufschlag sowie sonstige auf oder in Bezug auf die Schuldverschreibungen zahlbaren\nBeträge.',
     'Kapital', 'in diesen\nAnleihebedingungen',
     'den Rückzahlungsbetrag der\nSchuldverschreibungen;\nden\nvorzeitigen\nRückzahlungsbetrag\nder\nSchuldverschreibungen;  den Wahl-Rückzahlungsbetrag (Call)\nder Schuldverschreibungen;   sowie jeden\nAufschlag sowie sonstige auf oder in Bezug auf die Schuldverschreibungen zahlbaren\nBeträge'),
    ('U03-interest', 'REFERENCE_EXPANSION',
     'Bezugnahmen in diesen Anleihebedingungen auf Zinsen auf die\nSchuldverschreibungen sollen, soweit anwendbar, sämtliche gemäß § 7 zahlbaren\nzusätzlichen Beträge einschließen.',
     'Zinsen', 'in diesen Anleihebedingungen',
     'sämtliche gemäß § 7 zahlbaren\nzusätzlichen Beträge'),
    ('U12-takeover-act', 'LEGISLATIVE_ALIAS',
     'Wertpapiererwerbs- und Übernahmegesetzes (WpÜG)', 'WpÜG', None,
     'Wertpapiererwerbs- und Übernahmegesetzes'),
    ('U06-tax-early-amount', 'PURPOSE_CONDITIONED_AMOUNT',
     'Für die Zwecke des Absatzes (2)  dieses § 5, entspricht der vorzeitige Rückzahlungsbetrag einer\nSchuldverschreibung dem Rückzahlungsbetrag.',
     'vorzeitige Rückzahlungsbetrag', 'Für die Zwecke des Absatzes (2)  dieses § 5',
     'dem Rückzahlungsbetrag'),
    ('U07-makewhole-early-amount', 'PURPOSE_CONDITIONED_AMOUNT',
     'Für die Zwecke des Absatzes [(5)] dieses § 5 entspricht der vorzeitige\nRückzahlungsbetrag einer Schuldverschreibung (i) dem Rückzahlungsbetrag oder (ii),\nfalls höher, dem abgezinsten Marktwert der Schuldverschreibung.',
     'vorzeitige\nRückzahlungsbetrag', 'Für die Zwecke des Absatzes [(5)] dieses § 5',
     '(i) dem Rückzahlungsbetrag oder (ii),\nfalls höher, dem abgezinsten Marktwert der Schuldverschreibung'),
    ('U11-tax-haven-act', 'LEGISLATIVE_ALIAS',
     'Gesetzes zur Abwehr von Steuervermeidung und unfairem\nSteuerwettbewerb (Steueroasen-Abwehrgesetz)',
     'Steueroasen-Abwehrgesetz', None,
     'Gesetzes zur Abwehr von Steuervermeidung und unfairem\nSteuerwettbewerb'),
]


def main():
    started = time.monotonic()
    assert not (PREP / 'candidate/unquoted_definitions.py').exists()
    products = {k: prior.read(ROOT / r['path']) for k, r in prior.read(prior.PRODUCTS)['products'].items()}
    answer = prior.read(prior.HERE / 'ordinary-answer.json.gz')
    text = products['P2']['payload']['assembly']['continuous_text']
    expected = []
    for identity, kind, excerpt, label, scope, value in ROWS:
        assert text.count(excerpt) == 1, identity
        start = text.index(excerpt)
        def span(raw):
            if raw is None:
                return None
            a = start + excerpt.index(raw)
            return {'start': a, 'end': a + len(raw), 'raw': raw}
        expected.append({'review_record': identity, 'kind': kind,
                         **span(excerpt), 'term': span(label), 'scope': span(scope), 'value': span(value),
                         'label': ' '.join(label.split())})
    prior.save(PREP / 'expected.json', {'candidates': expected, 'count': 7,
        'missing_literal_declaration': {'term': 'Zinsperiode', 'start': 7725, 'end': 7736},
        'untested': ['other unquoted constructions', 'appointments', 'tables', 'implicit equivalence', 'general recall']})
    prior.save(PREP / 'source-freeze.json', {'created_at': datetime.now(timezone.utc).isoformat(),
        'candidate_absent': True, 'products_sha256': digest(products), 'ordinary_answer_sha256': digest(answer),
        'plan_sha256': prior.sha(ROOT / PLAN), 'expected_sha256': prior.sha(PREP / 'expected.json'),
        'wall_seconds': time.monotonic() - started})
    print('Frozen seven independently read unquoted expression/term/scope/value spans')


if __name__ == '__main__':
    main()
